def cyk_algorithm(rules_binary, rules_terminal, words, start_symbol='S'):
    n = len(words)
    # dp[length][start_index] stores a set of non-terminals
    # Length is 1-indexed (l from 1 to n), start_index is 0-indexed (i from 0 to n-l)
    dp = collections.defaultdict(lambda: collections.defaultdict(set))

    # Step 1: Initialize for length 1 substrings
    for i in range(n):
        word = words[i]
        for nt, term in rules_terminal:
            if term == word:
                dp[1][i].add(nt)

    # Step 2: Iterate for lengths from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1): # Start index of substring
            j = i + length - 1         # End index of substring
            for k in range(i, j):      # Split point
                # Substring 1: words[i...k], length (k - i + 1)
                # Substring 2: words[k+1...j], length (j - (k+1) + 1) = (j - k)
                len1 = k - i + 1
                len2 = j - k

                for A, B, C in rules_binary:
                    if B in dp[len1][i] and C in dp[len2][k+1]:
                        dp[length][i].add(A)

    # Step 3: Check if start_symbol is in dp[n][0] (the cell for the entire string)
    return start_symbol in dp[n][0]

